const spriteOverrides = process.env.E2E_NAV_SPRITE_ICONS
if (spriteOverrides) {
  const overrideMap = JSON.parse(spriteOverrides)
  await page.evaluate((icons) => {
    const svgNamespace = 'http://www.w3.org/2000/svg'
    const xlinkNamespace = 'http://www.w3.org/1999/xlink'
    for (const [title, key] of Object.entries(icons)) {
      const item = [...document.querySelectorAll('.top-nav .nav-item')]
        .find((entry) => entry.querySelector('.nav-text')?.textContent.trim() === title)
      const previousIcon = item?.querySelector('.nav-item__icon')
      if (!previousIcon) continue
      const svg = document.createElementNS(svgNamespace, 'svg')
      svg.setAttribute('class', 'nav-item__icon')
      svg.setAttribute('aria-hidden', 'true')
      const use = document.createElementNS(svgNamespace, 'use')
      use.setAttributeNS(xlinkNamespace, 'xlink:href', `#navbar-icon-${key}`)
      use.setAttribute('href', `#navbar-icon-${key}`)
      svg.appendChild(use)
      previousIcon.replaceWith(svg)
    }
  }, overrideMap)
  console.log(`[navbar-visual] sprite overrides=${Object.keys(overrideMap).length}`)
}
await page.waitForTimeout(300)
fs.mkdirSync(ARTIFACT_DIR, { recursive: true })
